INSERT INTO feature VALUES('e-graphs','rewriting','Congruence closure and extraction',NULL,'partial','notable',NULL,'An e-graph closes equations over the terms of a Lawvere theory''s table under congruence. The table holds each term once, so its places are the nodes, and the e-graph adds a union-find, the parents of each class and a proof forest. Each union keeps its reason, an input equation at an instance or a congruence of two nodes whose arguments are equal, and the explanation of two terms of one class replays against the table and the equations alone, each forged step refused by name. A union puts its class on a worklist and the rebuild repairs each class once; an e-class analysis keeps on each class the join of its nodes'' data; a round of saturation reads every match before it applies one, a match binding each variable to a class, so the order of the equations does not change the classes; a union inside one class is kept with its reason. On each ground block of the corpus the e-graph joins exactly the terms with one normal form, and on each other first-order block with a constant, saturation from the block''s ground terms up to five nodes does. Extraction as a cost fold (#5978), blocks admitted by saturation (#5984) and the loops of redundant unions as a homotopy basis (#5979) are owed.','theory-e-graphs','crates/theory-e-graphs/tests/graph.rs crates/theory-e-graphs/tests/explain.rs crates/theory-e-graphs/tests/analysis.rs crates/theory-e-graphs/tests/phases.rs crates/surface-lowering/tests/e_graphs.rs',NULL,'#5978 #5984 #5979');
